let mapVisitPending=false;async function visitNode(n){if(mapVisitPending||busy||state?.phase!=='world'||!accessible(n))return;mapVisitPending=true;try{await selectNode(n);if(n.kind==='shrine'){if(state.campaign.location!==n.id){busy=true;await moveParty(n);state.campaign.location=n.id;busy=false;placeParty();save();}mapOverlay();return;}if(n.kind!=='merchant')await travel();}finally{mapVisitPending=false;}}
$('forest-map').onclick=event=>{if(busy||state?.phase!=='world'||$('map-dialog').open||event.target?.closest?.('button'))return;const rect=$('forest-map').getBoundingClientRect(),goal={x:(event.clientX-rect.left)/rect.width*100,y:(event.clientY-rect.top)/rect.height*100},route=MouseNavigation.route(state.campaign.viewChapter,coordinates(state.campaign.location),goal,!RegionGates.open(state.campaign.viewChapter,state.campaign.completed));if(!route){$('explore-tip').textContent='Click an open path. The sealed boss passage must be cleared first.';return;}MouseNavigation.path=route;$('mouse-destination').style.left=goal.x+'%';$('mouse-destination').style.top=goal.y+'%';$('mouse-destination').hidden=false;$('explore-tip').textContent='Walking along the path · WASD or arrows take over at any time.';};
async function selectNode(n){if(busy)return;if(n.global)n=camp();destination=n;$('location-name').textContent=n.name;$('location-copy').textContent=n.description;$('world-message').textContent='';$('merchant-stock').hidden=n.kind!=='merchant';$('moonwell-choices').hidden=n.kind!=='shrine';$('travel').disabled=['merchant','shrine'].includes(n.kind);$('travel').textContent=n.kind==='battle'?'Enter encounter →':'Explore this path →';if(n.kind==='merchant'){if(state.campaign.location!==n.id){busy=true;await moveParty(n);state.campaign.location=n.id;busy=false;}placeParty();save();shop();mapOverlay();}}
function shop(){const box=$('merchant-stock');box.replaceChildren();const greeting=document.createElement('p');greeting.textContent='Elowen, the wayfarer: “My courier vanished near the old ruins. Bring back his signet and I will help your journey.”';box.append(greeting);const quest=document.createElement('button');quest.textContent=state.campaign.courierQuest==='recovered'?'Return courier’s signet · 30 gold + potion':state.campaign.courierQuest==='accepted'?'Courier quest accepted · search the ruins':state.campaign.courierQuest==='complete'?'Courier rescued · reward collected':'Accept Elowen’s courier quest';quest.disabled=['accepted','complete'].includes(state.campaign.courierQuest);quest.onclick=()=>{if(busy)return;if(state.campaign.courierQuest==='recovered'){state.campaign.courierQuest='complete';state.gold+=30;state.campaign.potions=Math.min(99,state.campaign.potions+1);state.treasure.push('Elowen’s gratitude');log('Returned the courier’s signet: earned 30 gold and a potion.');}else if(state.campaign.courierQuest===null){state.campaign.courierQuest=state.campaign.completed.includes('ruins')?'recovered':'accepted';log('Accepted Elowen’s missing courier quest.');}world();selectNode(nodes.find(n=>n.id==='merchant'));};box.append(quest);HEROES.forEach((h,i)=>{const b=document.createElement('button');b.textContent=`${h.name}: +5 weapon damage · 40 gold`;b.disabled=!!state.campaign.upgrades[i]||state.gold<40;b.onclick=()=>{if(state.gold<40||state.campaign.upgrades[i])return;state.gold-=40;state.campaign.upgrades[i]=1;log(h.name+' upgraded their weapon.');audio.play('chime');world();selectNode(nodes.find(n=>n.id==='merchant'));};box.append(b);});const potion=document.createElement('button');potion.textContent='Healing potion · 15 gold';potion.disabled=state.gold<15||state.campaign.potions>=99;potion.onclick=()=>{if(state.gold<15||state.campaign.potions>=99)return;state.gold-=15;state.campaign.potions++;world();selectNode(nodes.find(n=>n.id==='merchant'));};box.append(potion);const ward=document.createElement('button');ward.textContent='Party travel armor · 60 gold · reduce incoming damage 10%';ward.disabled=!!state.campaign.ward||state.gold<60;ward.onclick=()=>{if(busy||state.campaign.ward||state.gold<60)return;state.gold-=60;state.campaign.ward=1;log('Equipped travel armor for the entire party.');world();selectNode(nodes.find(n=>n.id==='merchant'));};box.append(ward);}
async function travel(){if(state?.phase!=='world'||busy||!destination||['merchant','shrine'].includes(destination.kind)||!accessible(destination))return;const n=destination;busy=true;$('travel').disabled=true;const distance=await moveParty(n);state.campaign.roadTrips=(state.campaign.roadTrips||0)+1;if(!state.campaign.resumeRoad&&RoadRules.shouldAmbush(distance,state.campaign,Math.random())){state.campaign.pendingJourney={to:n.id,from:state.campaign.location,chapter:state.campaign.viewChapter};state.campaign.roadTrips=0;const ambush=nodes.find(x=>x.id==='road'+state.campaign.viewChapter);state.encounter=ambush.encounter;state.campaign.battleNode=ambush.id;state.enemyHp=encounter().hp;state.phase='arrival';state.actor=state.hp.findIndex(h=>h>0);if(state.actor<0){state.hp=HEROES.map((_,i)=>maxHp(i));state.actor=0;}state.campaign.focus=state.campaign.talents.insight;state.campaign.shield=0;state.campaign.acted=[];state.campaign.streak=0;state.campaign.battlePerfects=0;state.campaign.stagger=0;busy=false;save();await arrival(true);return;}delete state.campaign.resumeRoad;delete state.campaign.pendingJourney;busy=false;state.campaign.location=n.id;if(n.kind==='battle'){state.encounter=n.encounter;state.campaign.battleNode=n.id;state.enemyHp=encounter().hp;state.phase='arrival';state.actor=state.hp.findIndex(h=>h>0);if(state.actor<0){state.hp=HEROES.map((_,i)=>maxHp(i));state.actor=0;}state.campaign.focus=state.campaign.talents.insight;state.campaign.shield=0;state.campaign.acted=[];state.campaign.streak=0;state.campaign.battlePerfects=0;state.campaign.stagger=0;save();await arrival(true);return;}const previousPotions=state.campaign.potions;if(n.kind==='treasure'){state.campaign.potions=Math.min(99,state.campaign.potions+2);state.gold+=15;state.treasure.push('Wayfarer supply cache');log('Found two healing potions and 15 gold.');}else if(n.kind==='spring'){state.hp=state.hp.map((hp,i)=>Math.min(maxHp(i),hp+Math.ceil(maxHp(i)*.5)));state.treasure.push(n.name+' blessing');log('Restored the party at '+n.name+'.');audio.play('heal');}else if(n.kind==='shrine'){state.hp=HEROES.map((_,i)=>maxHp(i));state.treasure.push('Moonwell blessing');state.campaign.potions=Math.min(99,state.campaign.potions+1);log('The Moonwell restored every hero and gifted a potion.');audio.play('heal');}state.campaign.completed.push(n.id);world();mapOverlay(n.name,n.kind==='treasure'?'Supply cache collected! +'+(state.campaign.potions-previousPotions)+' healing potions · +15 gold. Your supplies are now in the pack below.':'The spring restored up to half of each hero’s maximum HP. Your updated health is shown below.');}
