function win(){enemyRenderer?.setState('defeat');const e=encounter(),n=nodes.find(n=>n.id===state.campaign.battleNode);if(!state.campaign.completed.includes(n.id)){state.xp+=e.xp;state.gold+=e.gold;state.treasure.push(e.treasure);state.campaign.completed.push(n.id);const earnedRunes=1+(state.encounter%4===3?1:0)+(state.campaign.battlePerfects>0?1:0);state.campaign.runes+=earnedRunes;log('Earned '+earnedRunes+' forge runes'+(state.campaign.battlePerfects>0?' with a perfect-defense bonus.':'.'));if(n.id==='ruins'&&state.campaign.courierQuest==='accepted'){state.campaign.courierQuest='recovered';state.treasure.push('Courier’s signet');log('Found the missing courier sheltering in the ruins. Return his signet to Elowen.');}log('Won '+e.name+' and earned '+e.gold+' gold.');}const old=state.level;state.level=Math.min(20,1+Math.floor(state.xp/120));state.hp=state.hp.map((hp,i)=>state.level>old?maxHp(i):Math.min(maxHp(i),hp+Math.ceil(maxHp(i)*.25)));state.phase=!n.hidden&&stage()===encounters.length?'complete':'victory';if(n.id==='m'+state.encounter&&(state.encounter+1)%4===0&&stage()<encounters.length)state.campaign.nextChapter=Math.floor(stage()/4);audio.play('victory');renderers.forEach(r=>r.setState('victory'));save();}
function result(){busy=false;show('result');forgeUI();const dead=state.phase==='defeat',complete=state.phase==='complete',e=encounter();$('result-eyebrow').textContent=dead?'THE FOREST REMEMBERS':complete?'THE JOURNEY IS COMPLETE':'PATH CLEARED';$('result-title').textContent=dead?'A chance to rise':complete?'The beacons shine again':state.campaign.nextChapter?'Chapter '+Math.floor((state.encounter+1)/4)+' complete':'Victory!';$('result-copy').textContent=dead?'Retry with full health. Earlier rewards and upgrades remain.':complete?FOREST_STORY.areas[state.campaign.battleNode].victory:FOREST_STORY.areas[state.campaign.battleNode].victory;$('reward').textContent=state.campaign.pendingJourney&&!dead?'Road cleared · continue to '+(nodes.find(n=>n.id===state.campaign.pendingJourney.to)?.name||'your destination')+' · Road rewards are earned once per region':dead?`${state.correct} correct answers · ${state.wrong} mistakes`:`+${e.xp} XP · +${e.gold} gold · ${e.treasure}\nLevel ${state.level} · ${state.gold} total gold`;$('advance').textContent=dead?'Retry encounter':state.campaign.pendingJourney?'Continue to '+(nodes.find(n=>n.id===state.campaign.pendingJourney.to)?.name||'your destination')+' →':complete?'Play again':state.campaign.nextChapter?'Journey to '+JOURNEY_CHAPTERS[state.campaign.nextChapter].name+' →':'Return to region map →';}

function coordinates(id){const p=state.campaign.explorePosition;if(ExploreRules.valid(p,state.campaign.viewChapter,MapRoutes.graphs))return p;const g=MapRoutes.graphs[state.campaign.viewChapter];return g.points.get(id)||g.points.get('entry');}
function placeParty(){const at=coordinates(state.campaign.location),group=$('map-party');group._storyRenderers?.forEach(r=>r.destroy());group._storyRenderers=[];MapWalkers.reset(group,at,state.campaign.viewChapter);updateWorldCamera();}
async function moveParty(n){if(directDiscovery)return 0;delete state.campaign.explorePosition;const route=MapRoutes.route(state.campaign.viewChapter,state.campaign.location,n.id),distance=RoadRules.distance(route);show('road');JourneyArt.scene($('road-scene'),n.id);$('road-destination').textContent='Travelling to '+n.name;$('road-narration').textContent=state.campaign.viewChapter===0?'Boots on the forest trail. Leaves stir beyond the road.':state.campaign.viewChapter===1?'The party follows the mountain trail through wind and snow.':state.campaign.viewChapter===2?'Footsteps echo between the city’s ruined arches.':'Sea wind carries the sound of waves along the coastal trail.';const group=$('road-party');StoryPresentation.party(group,'road');const animation=group.animate([{transform:'translateX(-35%)',opacity:0},{transform:'translateX(0)',opacity:1,offset:.2},{transform:'translateX(70%)',opacity:1,offset:.85},{transform:'translateX(90%)',opacity:0}],{duration:MotionPreference.reduced()?80:Math.max(2200,Math.min(6000,distance*65)),easing:'linear',fill:'forwards'});try{await animation.finished;}finally{animation.cancel?.();show('world');placeParty();}return distance;}
function prologue(){busy=false;show('prologue');StoryPresentation.party($('prologue-party'),'opening').forEach(r=>r.setState('idle'));$('prologue-text').replaceChildren();FOREST_STORY.opening.forEach(t=>{const p=document.createElement('p');p.textContent=t;$('prologue-text').append(p);});}
async function arrival(animate){show('arrival');busy=true;$('begin-encounter').disabled=true;await RegionLoader.prepare(state.campaign.viewChapter,state.encounter);const tale=FOREST_STORY.areas[state.campaign.battleNode];$('arrival-chapter').textContent='CHAPTER '+(Math.floor(state.encounter/4)+1)+' · A NEW DANGER';$('arrival-title').textContent=encounter().name;StoryPresentation.scene($('arrival-scene'),state.campaign.battleNode);const group=$('arrival-party');StoryPresentation.party(group,'arrival');$('arrival-speaker').textContent=tale.speaker+' · Arrival';$('arrival-narration').textContent=tale.arrival;$('arrival-danger').textContent='Know your enemy: '+tale.danger;if(animate)await StoryPresentation.walk(group,'enter');else group.style.transform='translateX(0)';group._storyRenderers?.forEach(r=>r.setState('idle'));busy=false;$('begin-encounter').disabled=false;$('begin-encounter').focus();}
async function departure(){show('journey');const tale=FOREST_STORY.areas[state.campaign.battleNode];$('journey-title').textContent=stage()===encounters.length?'The Beacon shines again':'The party journeys onward';$('journey-narration').textContent=tale.victory+(state.campaign.battleNode==='ruins'&&state.campaign.courierQuest==='recovered'?' A frightened courier emerges from behind a broken arch. He gives Thorin his signet and asks him to tell Elowen he is safe.':'');StoryPresentation.scene($('journey-scene'),state.campaign.battleNode,state.phase==='complete'||state.campaign.battleNode==='m11');StoryPresentation.party($('journey-party'),'departure');await StoryPresentation.walk($('journey-party'),'leave');}
$('begin-chapter').onclick=()=>{if(state.phase!=='prologue')return;log('Thorin began the quest to relight the Beacon of Asterfall.');world();};
$('begin-encounter').onclick=()=>{if(busy||state.phase!=='arrival')return;state.phase='battle';log('Entered '+encounter().name+'.');save();battle();};


